def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def step_away(a, b):
        return [sign(a[0] - b[0]), sign(a[1] - b[1])]

    def first_point(items):
        if not items:
            return None
        p = items[0]
        if isinstance(p, dict):
            return [p.get("x", 0), p.get("y", 0)]
        return list(p)

    def nearest(points, origin):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, dict):
                x, y = p.get("x", 0), p.get("y", 0)
            else:
                x, y = p[0], p[1]
            d = abs(x - origin[0]) + abs(y - origin[1])
            if best is None or d < best_d:
                best = [x, y]
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position", [0, 0])
    opp_pos = observation.get("opponent_position", [0, 0])
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward([sx, sy], [ox, oy])
        gw = observation.get("grid_width", 0) - 1
        gh = observation.get("grid_height", 0) - 1
        corners = ([0, 0], [0, gh], [gw, 0], [gw, gh])
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return step_toward([sx, sy], target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = nearest(targets, [sx, sy])
        if target is None:
            gw = observation.get("grid_width", 1) - 1
            gh = observation.get("grid_height", 1) - 1
            target = [gw // 2, gh // 2]
        return step_toward([sx, sy], target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources, [sx, sy])
    if target is not None:
        return step_toward([sx, sy], target)

    return step_toward([sx, sy], [ox, oy])

